# -*- coding: utf-8 -*-
"""矛盾驱动补盲 · 批次C7（v5 新域 10 簇+直答）

补：AI替代工作/AI版权/AI偏见/自由职业/远程办公/生育成本/熬夜/外卖/网课/鸡娃
"""
def patch(path):
    src = open(path, encoding="utf-8").read()
    anchor_c = '    "概念形成": ["概念形成", "原型理论", "样例理论", "概念是怎么形成的"],'
    new_c = '''    "AI替代工作": ["AI取代工作", "AI替代", "我的工作被AI", "AI抢饭碗",
                  "重复劳动", "淘汰落后岗位", "人去做创造", "AI时代不可替代",
                  "AI会取代", "被AI替代", "AI替代人"],
    "AI创作版权": ["AI用我的画训练", "AI训练算不算偷", "AI生成版权",
                  "AI学习人类作品", "算侵权", "AI生成的内容", "创作者保护",
                  "AI创作", "AI作品", "AI画画"],
    "算法偏见": ["算法推荐同质", "越刷越同质", "AI评分冤枉", "算法客观",
                "大数据杀熟", "算法偏见", "被算法不公", "算法不公平",
                "推荐算法", "算法歧视", "AI偏见"],
    "自由职业": ["越来越多人裸辞", "想裸辞", "自由职业真的自由", "没有稳定工作",
                "自由职业逃避", "适不适合自由职业", "自由职业稳定收入",
                "自由职业", "接单", "副业", "数字游民"],
    "远程办公": ["远程办公又爱又恨", "居家办公效率", "老板不放心", "远程回办公室",
                "远程办公高效", "远程和坐班", "居家办公", "在家办公",
                "线上办公", "远程工作", "居家工作"],
    "生育成本": ["年轻人不想生孩子", "养一个孩子花多少钱", "生孩子被社会绑架",
                "降低生育代价", "生不生听谁的", "生育成本", "养孩子贵",
                "不想生", "催生", "育儿成本", "生孩子"],
    "熬夜": ["熬夜伤身", "戒不掉熬夜", "几点睡算熬夜", "晚睡晚起规律",
            "怎么戒掉熬夜", "戒熬夜", "熬夜", "睡得晚", "夜猫子",
            "凌晨睡", "睡眠不足"],
    "外卖健康": ["天天吃外卖", "外卖不健康", "不点外卖加班吃", "吃得健康不费时间",
                "外卖族自救", "外卖健康", "快餐不健康", "外卖油腻",
                "点外卖", "外卖党", "吃外卖"],
    "网课效果": ["网课效果不如线下", "上网课走神", "网课便宜方便", "让网课有效果",
                "线上线下结合", "网课效果", "上网课", "线上课",
                "直播课", "网课分心", "网课自律"],
    "鸡娃": ["家长都拼命鸡娃", "鸡娃有没有用", "不鸡娃孩子落后", "鸡娃心理问题",
            "鸡娃和快乐教育", "鸡娃的度", "鸡娃", "报班", "兴趣班",
            "学前班", "鸡娃焦虑", "育儿焦虑"],'''
    assert anchor_c in src
    src = src.replace(anchor_c, new_c + "\n    " + anchor_c, 1)

    anchor_d = '    "概念形成": "概念形成是人获得概念的方式——原型理论（典型样例）、样例理论（具体实例）、理论观（嵌入知识网络）；对应知识卡组织",'
    new_d = '''    "AI替代工作": "AI替代工作，是『效率革命』和『就业冲击』的矛盾——AI先替代的是重复性/规则性工作（客服/数据录入/初级文书），因为这些是『模式识别』，正是AI强项。真相：①替代的次序——不是按职业贵贱，是按『可自动化程度』：越重复越先被替代（司机/会计/翻译），越需要判断和人际越安全（医生/教师/管理者）；②『人去创造』是安慰不是全貌——AI替代的岗位需要新技能，但转岗不是一键切换，中年被替代者再培训很痛苦；③淘汰落后岗位是进步的必然——半真半假：进步淘汰的是『工作方式』不是『人』，但社会要为被替代者提供过渡（培训/保障），否则进步是少数人的进步。应对：①叠加AI而不是对抗——会用AI的人替代不会用的人（人+AI > AI > 人），把AI当工具升级自己；②往AI够不着的地方走——复杂判断/情感连接/责任承担（AI可以写方案，不能为方案负责）；③持续学习是唯一护城河——岗位会消失，能力不会，保持学习能力的人永远有下一个岗位。AI时代人不可替代的：做决策担责任、建立信任关系、创造真正的新东西（不是重组旧东西）",
    "AI创作版权": "AI用人类作品训练算不算偷，是『学习』和『复制』的边界问题——AI训练读遍全网作品来学规律（像人读万卷书），但它生成的『新』作品本质上是对学习样本的重组。三视角：①『像人学习一样』不成立——人学习后创作有独创性贡献（消化吸收再创造），AI是概率性拼贴（统计规律重组），没有『理解』只有『模式』；②版权归属——AI生成的作品版权模糊：人给的提示词算创作吗？AI算作者吗？目前各国普遍倾向『人类有足够创造性贡献才算作者』；③创作者损失是真实的——AI用你的画风生成替代品，你的订单减少，这是实质损害不是抽象争议。保护自己三招：①技术维权——用AI指纹/水印工具标记作品，被发现抄袭可追溯；②差异化——做AI难以复制的（个人经历/现场感/互动性），AI能批量产的是『可标准化』的，你做不可标准化的；③参与规则——支持给训练数据付费的合规模型，用脚投票。AI创作和人类创作共处：AI是工具不是作者，人提供意图/审美/责任——协作优于对抗，但规则（署名/分成/训练许可）要先立",
    "算法偏见": "算法推荐越刷越同质、评分可能冤枉人，是『算法优化点击率』vs『用户真实利益』的矛盾——算法目标函数是『让你停留更久』（广告收益），不是『对你好』，所以它给你喂同质内容（确认偏误的放大器）让你沉浸。真相：①同质化不是算法坏，是目标函数使然——它发现你喜欢A就推A，你越看越固化（信息茧房），这是商业逻辑不是阴谋；②算法评分冤枉人——模型用历史数据训练（含历史偏见：过去的歧视会被学进去），『客观』是假象：算法是中立的工具，训练数据和目标函数才决定它的价值观；③大数据杀熟——不是所有平台都做，但『价格歧视』技术上存在（根据你的消费力定价），监管在跟进。应对：①主动打破茧房——搜索/关注反方观点、少用『推荐』多用『搜索』、定期清理推荐偏好；②被冤枉怎么办——申诉渠道（各平台有反馈）、留证据、找人工客服（算法判不了人情）；③心态——算法不是神，它是公司的工具，别让它定义你。减少偏见的方向：训练数据去偏/算法审计/监管透明（怎么判的公开）",
    "自由职业": "想裸辞、自由职业真的自由吗——『自由』的另一面是『不确定』：时间自由≠财务自由，没人管你≠没人欠你（没有保底工资/社保/年终奖）。真相：①自由职业的自由是假的自由——你自由的是『在哪干活』，不自由的是『没活干』：收入波动大（这个月多下个月零），社保要自己交，休假等于没收入；②裸辞是情绪不是职业规划——裸辞一时爽，求职火葬场（没有退路时谈判劣势），想清楚再辞；③自由职业是不是逃避职场——有逃避型（受不了管束）也有进取型（主动选择更高回报），关键是你能不能自我驱动（没人安排你，你会不会躺）。判断适不适合：①自律测试——不上班时你能保持产出吗（先试副业3个月验证）；②财务缓冲——至少6个月生活费，否则心态崩；③技能可售性——你的技能有没有市场需求（有人愿意单独为它付钱）。保证稳定收入：多渠道（主业/副业/被动收入）、合同制（先签约后干活）、客户积累（老客户>新客户）。自由职业的真相：适合自我驱动+有缓冲+技能可售的人，不是逃离职场的出口",
    "远程办公": "远程办公又爱又恨，是『个人灵活性』和『组织协作』的矛盾——员工爱（省通勤/时间自由/舒适），企业怕（看不见人/协作慢/文化淡）。真相：①居家办公效率的真相——『深度工作』效率更高（没人打扰），『协作工作』效率更低（沟通成本高/信息延迟），所以写代码/写方案适合远程，头脑风暴/对齐不适合；②老板不放心的根源——不是员工偷懒，是『管理方式没跟上』：靠『看见人』管理（坐班制）失效，需要靠『结果管理』（目标/产出），很多管理者不会；③远程是否回办公室——趋势是混合办公（关键周面对面+平时远程），不是二选一。高效不失控三招：①结果对齐——每周目标明确（看产出不看工时），让老板看到结果而不是坐班；②仪式感——固定上下班时间/远程也有例会，避免『永远在线』（远程最大的坑是没边界，反而更累）；③定期线下——团队每季度聚一次，关系在线下建立，线上维护。选择：深度工作型岗位适合远程，协作管理型适合坐班，混合是多数人的最优解",
    "生育成本": "年轻人不想生孩子，是『养育成本爆炸』vs『生育回报下降』的理性选择——生孩子不再是稳赚的投资（过去养儿防老/增加劳动力），而是高成本项目（教育/医疗/住房/时间）且回报不确定。真相：①成本清单——教育（学区/补习/大学）、医疗、住房（要更大的房）、机会成本（尤其女性：产假后职业断层），一线城市养到大学百万起步；②不想生的深层——不是自私是『负责任的清醒』：给不了孩子好的条件，不生是对孩子负责（不生比生了养不起好）；③『不生孩子老了谁管』——养老靠的是钱和健康不是孩子（孩子有自己的压力），把养老绑在孩子身上是道德绑架。降低代价的出路：①社会层面——生育补贴/托育普惠/教育减负/女性职场保护（把成本社会化，别全压家庭）；②个人层面——想清楚再决定（生是选择不是任务），要生就规划（先存教育金/争取家庭支持）；③『生不生听谁的』——最终是夫妻共同决定，别人（父母/社会）的意见参考不执行。核心：生育是重大人生决策，成本真实存在，社会要分担、个人要清醒",
    "熬夜": "熬夜戒不掉，是『夜晚的自由』vs『白天的代价』——白天时间被工作/社交占据（不是自己的），晚上才有一点点『属于自己的时间』，熬夜是用健康换自由。真相：①熬夜的本质——不是失眠是『报复性熬夜』：白天越被剥夺，晚上越舍不得睡（用熬夜找回掌控感），戒不掉是因为白天没有属于自己的时间；②几点睡算熬夜——不以钟表论，以规律论：每天2点睡10点起且稳定=规律作息（晚睡型），今天11点明天3点=真熬夜（紊乱伤身）；③晚睡晚起算不算规律——算规律但有两坑：社会时钟不配合（上班9点）、褪黑素分泌受光照影响（长期昼夜颠倒伤代谢）。戒熬夜三招：①白天抢回一点自主时间——哪怕半小时（运动/爱好/独处），『报复性熬夜』的需求就小了（晚上没那么舍不得睡）；②睡前一小时做『关机仪式』——不碰手机（蓝光抑制褪黑素）、调暗灯光、固定流程（洗澡→阅读→关灯）；③别硬躺——躺20分钟睡不着就起来（做点无聊的事），别在床上焦虑（床=睡觉不是焦虑场）。核心：戒熬夜不是逼自己早睡，是让白天值得醒来、晚上舍得放下",
    "外卖健康": "天天吃外卖戒不掉，是『时间稀缺』vs『健康需要』的矛盾——外卖是时间的最优解（不花时间做饭洗碗），代价是油盐超标/食材不明/花费高。真相：①外卖不健康是结构性的——商家为好吃多用油盐糖（重口味掩盖食材），你点的『健康餐』也可能是料理包（预制菜），不是外卖全坏是外卖的利润结构导向重口；②『不点外卖加班吃什么』——真实困境：加班到9点没精力做饭，外卖是唯一选项——这是工作强度问题不是选择问题；③点健康的外卖可能吗——可以但费心（挑清淡商家/备注少油盐），成本是注意力。外卖族自救四招：①备『救急健康粮』——办公室囤即食燕麦/全麦面包/坚果/水果，加班晚了先垫一口再决定点不点（饿极了最容易乱点）；②点单技巧——选『蒸/煮/炖』少『炸/烤/炒』、备注『少油少盐』、加一份蔬菜（补纤维）；③周末备餐——周日做两三顿的量分装冷冻，工作日热一下（一周省5顿外卖）；④算健康账——外卖月支出+体检风险，比做饭的真实成本高。核心：健康不是顿顿自己做，是『多数时候合理』——用20%的准备覆盖80%的外卖",
    "网课效果": "网课效果不如线下，是『便利性』vs『学习深度』的矛盾——网课省时间省钱（随时学/名师多），但缺监督/缺互动/易分心（旁边就是手机）。真相：①网课分心的机制——线下有『在场压力』（老师看着/同学学着），线上没有社会在场感，大脑默认『可以摸鱼』；②网课差不是网课的错——是『把线下模式搬线上』的错：线下40分钟讲课线上也40分钟，没有利用线上优势（回放/倍速/互动工具），本质是照搬；③孩子上网课走神——孩子的自控力本来就没发育好，网课对自控要求更高（成人也摸鱼何况孩子）。让网课有效三招：①环境隔离——上课的空间固定（书桌不躺床）、手机放另一个房间、耳机戴上（物理屏蔽）；②主动学习代替被动听——边听边记/暂停复述/看完做3道题（网课最大优势是可暂停，用起来）；③线上线下的正确结合——知识讲解用线上（可回放），练习互动用线下（需要人），发挥各自优势。核心：网课不是线下替代品，是不同工具——用对场景才有效果",
    "鸡娃": "鸡娃（疯狂报班）是『竞争焦虑』vs『孩子童年』的矛盾——家长怕孩子落后（升学是排位赛），把焦虑转成报班（多学一点=多一分优势）。真相：①鸡娃有没有用——边际递减：报1-2个班有效（补短板/拓兴趣），报5-6个班无效（孩子疲于应付，学而不入，还可能厌学）；②鸡娃的真相是『剧场效应』——前排站起来后排必须站，家长不鸡就被裹挟着鸡（不是想鸡，是不鸡不安心）；③鸡娃鸡出心理问题——真实风险：孩子长期被安排（没自主时间）→ 厌学/焦虑/低自尊（『我只有考好才有价值』），这比少学几样东西代价大。平衡的度：①数量控制——同时≤2个班（一个补短板+一个真兴趣），留白时间（发呆/玩耍/自由是大脑发育需要）；②目的校准——报班为『孩子喜欢』不是『家长安心』（孩子喜欢的班是充电，不喜欢的班是耗电）；③焦虑管理——家长的焦虑自己消化（不是转给孩子），孩子的竞争力来自『内驱力』（自己想学）不是课时量。核心：鸡娃的度 = 留白 + 兴趣 + 内驱，用孩子喜欢的方式学，比堆课时持久",
    "概念形成": "概念形成是人获得概念的方式——原型理论（典型样例）、样例理论（具体实例）、理论观（嵌入知识网络）；对应知识卡组织",'''
    assert anchor_d in src
    src = src.replace(anchor_d, new_d, 1)
    open(path, "w", encoding="utf-8").write(src)
    print("patched")

